 [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int Position(IntPtr self,uint count,[MarshalAs(UnmanagedType.LPArray,SizeParamIndex=1)]IntPtr[] items,[MarshalAs(UnmanagedType.LPArray,SizeParamIndex=1)]Point[] points,uint flags);
